type Mode='express'|'courier'|'city'|'virtual';const orderNo=ref(''),mode=ref<Mode>('express'),expressType=ref(1),carriers=ref<CustomerWorkCarrier[]>([]),couriers=ref<CustomerWorkCourier[]>([]),templates=ref<CustomerWorkWaybillTemplate[]>([]),carrierIndex=ref(-1),courierIndex=ref(-1),templateIndex=ref(-1),cityIndex=ref(-1),tracking=ref(''),senderName=ref(''),senderPhone=ref(''),senderAddress=ref(''),virtualContent=ref(''),cargoWeight=ref(''),cityRemark=ref(''),split=ref(false),quantities=ref<Record<string,number>>({}),templateLoading=ref(false),scanning=ref(false),error=ref('');
const jobForms=ref<Record<number,{reason:string;tracking:string;label:string;reference:string}>>({});let templateEpoch=0,scanEpoch=0;
const scannerAvailable=ref(customerWorkWechatScannerAvailable());
