function clear(){templateEpoch++;scanEpoch++;carriers.value=[];couriers.value=[];templates.value=[];carrierIndex.value=-1;courierIndex.value=-1;templateIndex.value=-1;cityIndex.value=-1;mode.value='express';expressType.value=1;tracking.value='';senderName.value='';senderPhone.value='';senderAddress.value='';virtualContent.value='';cargoWeight.value='';cityRemark.value='';split.value=false;quantities.value={};templateLoading.value=false;scanning.value=false;error.value='';jobForms.value={};}
const manager=useCustomerWork({page:'delivery',query(query){orderNo.value=query.orderId!;},clear,async load(controller){const valid=controller.fence();await operations.load(orderNo.value);if(!valid())return;const authority=operations.bootstrap.value;if(!authority)return;
  const [express,staff,config]=await Promise.all([operations.read('/mobile/work/fulfillment/carriers',isCustomerWorkCarriers),operations.read('/mobile/work/fulfillment/couriers',isCustomerWorkCouriers),operations.read('/mobile/work/fulfillment/defaults',(data):data is {defaults:import('@/types/customerWorkFulfillment').CustomerWorkFulfillmentDefaults}=>!!data&&typeof data==='object'&&isCustomerWorkDefaults((data as {defaults?:unknown}).defaults))]);if(!valid()||operations.bootstrap.value!==authority)return;
  carriers.value=express.data.list;couriers.value=staff.data.list;const defaults=config.data.defaults;senderName.value=defaults.to_name;senderPhone.value=defaults.to_tel;senderAddress.value=defaults.to_add;carrierIndex.value=carriers.value.findIndex(row=>String(row.id)===defaults.config_export_id);mode.value=authority.data.order.product_type===3?'virtual':'express';
}}),operations=useCustomerWorkOperations(manager);
