function selected(event:{detail:{value:string|number}},length:number){const index=Number(event.detail.value);return Number.isInteger(index)&&index>=0&&index<length?index:-1;}
function chooseMode(value:Mode){if(operations.busy.value||!modes.value.some(row=>row.key===value&&row.available))return;scanEpoch++;scanning.value=false;mode.value=value;if(value==='virtual')split.value=false;error.value='';}
function chooseExpress(value:number){if(operations.busy.value||![1,2].includes(value)||value===2&&!operations.bootstrap.value?.data.actions.electronic_waybill.available)return;scanEpoch++;scanning.value=false;expressType.value=value;templateEpoch++;templates.value=[];templateIndex.value=-1;templateLoading.value=false;if(value===2)void loadTemplates();}
