function chooseCourier(event:{detail:{value:string|number}}){if(!operations.busy.value)courierIndex.value=selected(event,couriers.value.length);}function chooseTemplate(event:{detail:{value:string|number}}){if(!operations.busy.value)templateIndex.value=selected(event,templates.value.length);}function chooseCity(event:{detail:{value:string|number}}){if(!operations.busy.value)cityIndex.value=selected(event,cityProviders.value.length);}
async function loadTemplates(){const carrier=carriers.value[carrierIndex.value],authority=operations.bootstrap.value;if(!carrier||!authority||!authority.data.readiness.electronic.ready)return;const version=++templateEpoch,valid=manager.fence();templateLoading.value=true;try{const response=await operations.read('/mobile/work/fulfillment/templates',isCustomerWorkTemplates,{carrier_id:carrier.id});if(!valid()||version!==templateEpoch||carrier.id!==carriers.value[carrierIndex.value]?.id||expressType.value!==2)return;if(response.data.carrier_id!==carrier.id)throw Error('快递公司模板响应不匹配');templates.value=response.data.list;templateIndex.value=templates.value.findIndex(row=>row.temp_id===authority.data.defaults.express_temp_id);}catch(failure){if(valid()&&version===templateEpoch){const code=failure as {status?:unknown;httpStatus?:unknown};if(code.status===403||code.httpStatus===403){manager.invalidate(failure);return;}error.value=failure instanceof Error?failure.message:'当前快递模板读取失败';templates.value=[];templateIndex.value=-1;}}finally{if(valid()&&version===templateEpoch)templateLoading.value=false;}}
function previewTemplate(){const template=templates.value[templateIndex.value];if(operations.current()&&template?.pic&&customerWorkImage(template.pic))uni.previewImage({current:template.pic,urls:[template.pic]});}
function toggle(cart:CustomerWorkFulfillmentCart){if(!operations.busy.value)quantities.value[cart.cart_id]=quantities.value[cart.cart_id]?0:cart.surplus_num;}function quantity(cart:CustomerWorkFulfillmentCart,delta:number){if(!operations.busy.value&&quantities.value[cart.cart_id])quantities.value[cart.cart_id]=Math.max(1,Math.min(cart.surplus_num,quantities.value[cart.cart_id]!+delta));}
async function scan(){if(scanning.value||operations.busy.value||mode.value!=='express'||expressType.value!==1)return;const valid=manager.fence(),version=++scanEpoch,same=()=>valid()&&version===scanEpoch&&mode.value==='express'&&expressType.value===1;scanning.value=true;
  try{let value:string|null=null;
    // #ifdef H5
    value=await customerWorkWechatScan(same);
