    // #ifndef H5
    value=await new Promise<string|null>((resolve,reject)=>uni.scanCode({scanType:['barCode'],success:result=>resolve(result.result),fail:failure=>/cancel/iu.test(failure.errMsg||'')?resolve(null):reject(Error('条码扫描未完成，可手动输入'))}));
    // #endif
