 }catch(failure){if(operations.current())error.value=failure instanceof Error?failure.message:'原发货结果待核对';}}
function jobForm(id:number){return jobForms.value[id]??(jobForms.value[id]={reason:'',tracking:'',label:'',reference:''});}
async function recover(job:CustomerWorkWaybillJob,action:'APPLY_EXISTING'|'CONFIRM_ISSUED'|'CONFIRM_RETRY'|'CLOSE_NO_RETRY'){if(operations.busy.value)return;error.value='';try{const fresh=await operations.refreshJob(job.id);if(fresh.data.job.job_revision!==job.job_revision)throw Error('原任务状态已变化，请刷新后重新核对');const form=jobForm(job.id),reason=form.reason.trim();if(!reason||!customerWorkText(reason,500))throw Error('请填写本次恢复的核对理由');const payload:Record<string,unknown>={action,job_id:job.id,expected_job_revision:fresh.data.job.job_revision,reason};if(action==='CONFIRM_ISSUED'){const id=form.tracking.trim();if(!id||!customerWorkText(id,64)||/[\r\n]/u.test(id))throw Error('请填写渠道已签发的真实单号');payload.tracking_number=id;if(form.label.trim()){if(!customerWorkImage(form.label.trim()))throw Error('面单公开链接无效');payload.label_url=form.label.trim();}if(form.reference.trim()){if(!customerWorkText(form.reference.trim(),255))throw Error('渠道引用编号无效');payload.provider_reference=form.reference.trim();}}
  const kind=({APPLY_EXISTING:'waybill_apply_existing',CONFIRM_ISSUED:'waybill_confirm_issued',CONFIRM_RETRY:'waybill_confirm_retry',CLOSE_NO_RETRY:'waybill_close'} as const)[action],receipt=await operations.submit(kind,payload,'核对原面单恢复决定');if(operations.current()&&receipt?.outcome==='job-updated'){await manager.load();operations.error.value='恢复决定已记录，请查询原任务最新状态。';}
 }catch(failure){if(operations.current())error.value=failure instanceof Error?failure.message:'原面单恢复结果待核对';}}
function waybillStatus(value:string){return ({PENDING:'待签发',ENQUEUING:'准备进入签发队列',ENQUEUED:'已进入签发队列',PROCESSING:'渠道签发处理中',RETRYABLE:'等待安全重试',SENT:'面单与发货已确认',UNKNOWN:'签发结果未知',DEAD:'签发失败，待明确恢复',CLOSED:'任务已明确关闭'} as Record<string,string>)[value]||value;}
function cityStatus(value:string){return ({PENDING:'等待派单',PROCESSING:'派单处理中',ADMITTED:'渠道已受理，尚未确认送达',UNKNOWN:'派单结果未知，请查询原请求',REJECTED:'渠道已明确拒绝',REVOKED:'权限已撤销，原任务需核对',CANCELLED:'任务已取消',DELIVERED:'渠道已确认送达'} as Record<string,string>)[value]||value;}
</script>
